mapper.select:
SELECT t.id,t.owner_id,t.destination,t.destination_flag,t.entry_port,t.transport_mode, t.depart_date,t.arrive_date,t.return_date,t.capacity_qty, LEAST(t.remaining_slots,GREATEST(t.capacity_qty-(SELECT COALESCE(SUM(o.quantity),0) FROM t_orders o WHERE o.trip_id=t.id AND o.status NOT IN ('cancelled_no_fault','cancelled_breach','refunded','closed')),0)) AS remaining_slots, t.fee_mode,t.fee_value,t.trip_type,t.direction, (COALESCE(p.boost_factor,1)*100 + COALESCE(p.performance_score,60)*2 + COALESCE(p.star_avg,5)*10 + LEAST(COALESCE(p.deal_count,0),50)*1.5 + CASE WHEN COALESCE(p.deal_count,0)>0 THEN 30.0*COALESCE(p.ontime_count,0)/p.deal_count ELSE 15.0 END + CASE WHEN t.verify_status='approved' THEN 50 ELSE 0 END) AS rank_score FROM t_trips t JOIN t_profiles p ON t.owner_id=p.id WHERE t.verify_status='approved' AND t.status='active' AND t.visibility='public' AND t.return_date >= CURRENT_DATE() AND p.deleted_at IS NULL AND (p.banned_until IS NULL OR p.banned_until <= CURRENT_TIMESTAMP(3))
ORDER BY t.created_at DESC,t.id DESC ORDER BY p.performance_score DESC,t.id ASC ORDER BY rank_score DESC,t.id ASC
LIMIT #{limit}
